// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address zero = address(0);
        uint256 initialBalance = address(zero).balance;
        vm.deal(address(this), 1);
        // The owner is address(this) because the constructor sets owner = msg.sender
        c.sendTo(zero, 1);
        // Reference reverts so balance stays same; buggy sends 1 wei so balance changes
        assertTrue(address(zero).balance != initialBalance);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        uint256 balanceBefore = address(c).balance;
        vm.deal(address(this), 1);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: 1}(abi.encodeWithSignature("sendTo(address,uint256)", address(0), 1));
        uint256 balanceAfter = address(c).balance;
        assertTrue(ok == false && balanceBefore == balanceAfter);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address payable zeroAddress = payable(address(0));

        bool ok;
        try c.sendTo(zeroAddress, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference reverts (ok == false), buggy succeeds (ok == true)
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address receiver = address(0x123);
        vm.deal(address(c), 1 ether);
        vm.prank(address(c)); // not needed; just fund contract
        // Fund contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Now owner calls sendTo to send 1 ether to receiver
        address owner = address(this);
        vm.deal(owner, 1 ether); // ensure owner has ether (not needed)
        vm.prank(owner);
        c.sendTo{value: 0}(receiver, 1 ether);
        // After call: reference sends 1 ether, so contract balance = 0; mutant sends 0, contract balance = 1 ether
        assertTrue(address(c).balance == 0 ether);
    }
}
